UPDATE node_info SET state = #{state}
WHERE uuid IN

    #{uuids}

mapper.select:

SELECT tempni.* FROM (


    SELECT
    ni.name,ni.host_name,ni.ip,ni.uuid,ni.type,ni.tag,ni.user_name,ni.password,ni.state,ni.u_size,ni.cabinet_start,ni.snmp_port,ni.snmp_community,ni.remark,ni.cabinet_id
    FROM node_info ni

        LEFT JOIN node_cabinet nc ON ni.cabinet_id = nc.id

    WHERE ni.state != 3

        AND nc.room_id = #{params.roomId} AND nc.del_flag = 0



        AND ni.ip LIKE CONCAT('%', #{params.ip}, '%')



        AND ni.name like CONCAT('%', #{params.name}, '%')



        AND ni.state = #{params.state}



        AND ni.type = #{params.type}



        AND ni.tag = #{params.tag}



        AND ni.cabinet_id = #{params.cabinetId}




    ) tempni




    INNER JOIN

    system_node_rel snr ON tempni.uuid = snr.uuid

    WHERE snr.system_id = #{params.systemId}


SELECT tempni.*  FROM
(


    SELECT ni.name,ni.host_name,ni.ip,ni.uuid,ni.type,ni.tag,ni.user_name,ni.password,ni.state,ni.u_size,ni.cabinet_start,ni.snmp_port,ni.snmp_community,ni.remark,ni.cabinet_id FROM
    (
        SELECT DISTINCT n.* FROM node_group_rel ngr
        LEFT JOIN node_info n on ngr.uuid = n.uuid
        WHERE ngr.del_flag = 0  AND  ngr.group_id IN

            #{groupdIds}

    ) ni


        INNER JOIN node_cabinet nc ON ni.cabinet_id = nc.id


    WHERE ni.state != 3


        AND nc.room_id  = #{params.roomId}



        AND ni.ip LIKE CONCAT('%', #{params.ip}, '%')



        AND ni.name LIKE CONCAT('%', #{params.name}, '%')



        AND ni.state = #{params.state}



        AND ni.type = #{params.type}



        AND ni.tag = #{params.tag}



        AND ni.cabinet_id = #{params.cabinetId}





    ) tempni






    INNER JOIN

    system_node_rel snr ON tempni.uuid = snr.uuid

    WHERE snr.system_id = #{params.systemId}
